CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, password_hash text NOT NULL, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS profiles (id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, full_name text NOT NULL, role text NOT NULL CHECK(role IN ('candidate','recruiter')), gender text, photo_url text, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), recruiter_id uuid NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, company_name text NOT NULL, role text NOT NULL, description text NOT NULL, is_open boolean NOT NULL DEFAULT true, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL REFERENCES jobs(id) ON DELETE CASCADE, candidate_id uuid NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, candidate_name text NOT NULL, candidate_email text NOT NULL, resume_name text, resume_data text, resume_text text, status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','reviewing','selected','rejected')), semantic_score int, risk_level text, reasoning text, recommendation text, strengths text[] DEFAULT '{}', gaps text[] DEFAULT '{}', decision_message text, analysis_details jsonb, applied_at timestamptz DEFAULT now(), UNIQUE(job_id,candidate_id));
CREATE INDEX IF NOT EXISTS idx_jobs_recruiter ON jobs(recruiter_id); CREATE INDEX IF NOT EXISTS idx_apps_job ON applications(job_id); CREATE INDEX IF NOT EXISTS idx_apps_candidate ON applications(candidate_id); CREATE INDEX IF NOT EXISTS idx_apps_status ON applications(status);
